<?php
use App\Http\Controllers\{AdminController,AuthController,CustomerController}; use Illuminate\Support\Facades\Route;
Route::get('/',[CustomerController::class,'home'])->name('home'); Route::get('/menu',[CustomerController::class,'menu'])->name('menu');
Route::middleware('guest')->group(function(){Route::get('/login',[AuthController::class,'showLogin'])->name('login');Route::post('/login',[AuthController::class,'login']);Route::get('/register',[AuthController::class,'showRegister'])->name('register');Route::post('/register',[AuthController::class,'register']);}); Route::post('/logout',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware(['auth','role:customer'])->group(function(){Route::get('/cart',[CustomerController::class,'cartView'])->name('cart');Route::post('/cart/{food}',[CustomerController::class,'addCart'])->name('cart.add');Route::patch('/cart/items/{item}',[CustomerController::class,'updateCart'])->name('cart.update');Route::delete('/cart/items/{item}',[CustomerController::class,'removeCart'])->name('cart.remove');Route::get('/checkout',[CustomerController::class,'checkout'])->name('checkout');Route::post('/checkout',[CustomerController::class,'placeOrder'])->name('checkout.place');Route::get('/orders',[CustomerController::class,'orders'])->name('orders');Route::get('/orders/{order}',[CustomerController::class,'showOrder'])->name('orders.show');Route::post('/orders/{order}/cancel',[CustomerController::class,'cancel'])->name('orders.cancel');});
Route::prefix('admin')->name('admin.')->middleware(['auth','role:admin'])->group(function(){Route::get('/',[AdminController::class,'dashboard'])->name('dashboard');Route::get('/foods',[AdminController::class,'foods'])->name('foods');Route::post('/foods',[AdminController::class,'saveFood'])->name('foods.store');Route::put('/foods/{food}',[AdminController::class,'saveFood'])->name('foods.update');Route::delete('/foods/{food}',[AdminController::class,'deleteFood'])->name('foods.delete');Route::get('/categories',[AdminController::class,'categories'])->name('categories');Route::post('/categories',[AdminController::class,'saveCategory'])->name('categories.store');Route::put('/categories/{category}',[AdminController::class,'saveCategory'])->name('categories.update');Route::delete('/categories/{category}',[AdminController::class,'deleteCategory'])->name('categories.delete');Route::get('/orders',[AdminController::class,'orders'])->name('orders');Route::patch('/orders/{order}',[AdminController::class,'updateOrder'])->name('orders.update');Route::get('/payments',[AdminController::class,'payments'])->name('payments');Route::patch('/payments/{payment}',[AdminController::class,'verifyPayment'])->name('payments.update');Route::get('/inventory',[AdminController::class,'inventory'])->name('inventory');Route::post('/inventory/{food}',[AdminController::class,'adjustStock'])->name('inventory.adjust');Route::get('/discounts',[AdminController::class,'discounts'])->name('discounts');Route::post('/discounts',[AdminController::class,'saveDiscount'])->name('discounts.store');});
